fn check(ok:bool){if !ok{let _=fail(0);}}fn fail(x:u8)->u8{1/x}
trait Pick<'a>{type Out;const V:Self::Out;}struct Tag;#[derive(PartialEq,Eq)]struct R<'a>{r:&'a u8,n:u8}impl<'a>Pick<'a> for Tag{type Out=R<'a>;const V:Self::Out=R{r:&7,n:9};}struct S<'a,T>(&'a u8,T);impl<'a,T:Pick<'a>>S<'a,T>{const C:T::Out={let n=T::V;n};}fn f<'a>(_:&'a u8,x:R<'a>)->bool{match x{S::<'a,Tag>::C=>true,_=>false}}fn main(){let n=7;check(f(&n,R{r:&7,n:9}));check(!f(&n,R{r:&8,n:9}));}
